        existing_subnet_id = "<subnet-id>"
      }

      //Site local inside subnet
      inside_subnet {
        existing_subnet_id = "<subnet-id>"
      }

      //Workload subnet
      workload_subnet {    
        existing_subnet_id = "<subnet-id>"
      }
