                    },
                    "body": {
                        "name": "@{parameters('ip-prefix-set')}",
                        "namespace": "@{parameters('namespace')}",
                        "metadata": {
                            "name": "@{parameters('ip-prefix-set')}",
                            "namespace": "@{parameters('namespace')}",
                            "labels": {},
                            "annotations": {},
                            "description": "Last updated by Logic Apps at @{utcNow()}UTC",
                            "disable": false
                        },
                        "spec": {
                            "prefix": [
                                "@{outputs('Compose_Client_IP')}/32"
                            ],
                            "ipv6_prefix": [],
                            "ipv4_prefixes": [
                                {
                                    "ipv4_prefix": "@{outputs('Compose_Client_IP')}/32",
                                    "description": "Last updated by Logic Apps at @{utcNow()}UTC"
                                }
                            ],
                            "ipv6_prefixes": []
                        }
                    }
                }
            },
            "Response": {
                "runAfter": {
                    "HTTP_Update_IP": [
                        "Succeeded"
                    ]
                },
                "type": "Response",
                "kind": "Http",
                "inputs": {
                    "statusCode": 200,
                    "body": "Updated successfully to @{outputs('Compose_Client_IP')}/32"
                }
            },
            "Get_secret": {
                "runAfter": {
                    "Compose_Client_IP": [
                        "Succeeded"
                    ]
                },
                "type": "ApiConnection",
                "inputs": {
                    "host": {
                        "connection": {
                            "name": "@parameters('$connections')['keyvault']['connectionId']"
